import java.io.*;
import java.nio.file.*;

public class WriteFile {
    public static void main(String[] args) {
        Path file = Paths.get("students.txt");

        try (BufferedWriter writer = Files.newBufferedWriter(
                 file, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)) {

            writer.write("Ana Reyes,19,92.5");
            writer.newLine();
            writer.write("Jess Diaz,20,88.0");
            writer.newLine();
            writer.write("Marie Mendoza,21,95.25");
            writer.newLine();

            System.out.println("Written to " + file.toAbsolutePath());

        } catch (IOException e) {
            System.out.println("Could not write: " + e.getMessage());
        }
    }
}

import java.io.*;
import java.nio.file.*;

public class ReadFile {
    public static void main(String[] args) {
        Path file = Paths.get("students.txt");

        try (BufferedReader reader = Files.newBufferedReader(file)) {
            String line;
            int count = 0;
            double totalGrade = 0;

            while ((line = reader.readLine()) != null) {
                String[] fields = line.split(",");     // split the record into fields

                String name  = fields[0];
                int    age   = Integer.parseInt(fields[1]);
                double grade = Double.parseDouble(fields[2]);

                System.out.printf("%-16s %3d %8.2f%n", name, age, grade);

                count++;
                totalGrade += grade;
            }

            System.out.printf("%-16s %3s %8.2f%n", "AVERAGE", "", totalGrade / count);

        } catch (IOException e) {
            System.out.println("Could not read: " + e.getMessage());
        }
    }
}
